import{a as e,f as t,o as n,t as r}from"./app-SaVO6m06.js";var i=JSON.parse(`{"path":"/ai-test/basic/AI%E4%B8%8E%E6%9C%BA%E5%99%A8%E5%AD%A6%E4%B9%A0%E5%9F%BA%E7%A1%80.html","title":"AI与机器学习基础","lang":"zh-CN","frontmatter":{"breadcrumbExclude":true,"description":"AI与机器学习基础 Machine Learning 是指硬件机器训练一段 模型 的软件，使其能够根据 数据 和 算法 做出有用的预测或生成内容（包含文本、图片、音频或视频），让机器从 数据中学习 规律而非显式编程。 1. 机器学习的三大类 1.1 监督学习（Supervised Learning） 核心思想：用 带标签的数据 训练模型，让模型学会从输...","head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"AI与机器学习基础\\",\\"image\\":[\\"\\"],\\"dateModified\\":\\"2026-09-01T04:42:29.000Z\\",\\"author\\":[{\\"@type\\":\\"Person\\",\\"name\\":\\"Tommy\\",\\"url\\":\\"https://mister-hope.com\\"}]}"],["meta",{"property":"og:url","content":"https://mister-hope.github.io/ai-test/basic/AI%E4%B8%8E%E6%9C%BA%E5%99%A8%E5%AD%A6%E4%B9%A0%E5%9F%BA%E7%A1%80.html"}],["meta",{"property":"og:title","content":"AI与机器学习基础"}],["meta",{"property":"og:description","content":"AI与机器学习基础 Machine Learning 是指硬件机器训练一段 模型 的软件，使其能够根据 数据 和 算法 做出有用的预测或生成内容（包含文本、图片、音频或视频），让机器从 数据中学习 规律而非显式编程。 1. 机器学习的三大类 1.1 监督学习（Supervised Learning） 核心思想：用 带标签的数据 训练模型，让模型学会从输..."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"og:updated_time","content":"2026-09-01T04:42:29.000Z"}],["meta",{"property":"article:modified_time","content":"2026-09-01T04:42:29.000Z"}]]},"git":{"createdTime":1788237749000,"updatedTime":1788237749000,"contributors":[{"name":"pandacli","username":"pandacli","email":"tommyact07@gmail.com","commits":1,"url":"https://github.com/pandacli"}]},"readingTime":{"minutes":19.61,"words":5883},"filePathRelative":"ai-test/basic/AI与机器学习基础.md","excerpt":"\\n<blockquote>\\n<p><code>Machine Learning</code> 是指硬件机器训练一段 <code>模型</code> 的软件，使其能够根据 <code>数据</code> 和 <code>算法</code> 做出有用的预测或生成内容（包含文本、图片、音频或视频），让机器从 <code>数据中学习</code> 规律而非显式编程。</p>\\n</blockquote>\\n<div class=\\"language-text line-numbers-mode\\" data-highlighter=\\"shiki\\" data-ext=\\"text\\" style=\\"--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34\\"><pre class=\\"shiki shiki-themes one-light one-dark-pro vp-code\\"><code class=\\"language-text\\"><span class=\\"line\\"><span>假设我们想要创建一个用于 预测降雨量 的应用。</span></span>\\n<span class=\\"line\\"><span></span></span>\\n<span class=\\"line\\"><span>使用传统方法：</span></span>\\n<span class=\\"line\\"><span>如果采用传统方法，我们需要创建地球大气层和地表的基于物理学的表示形式，并计算大量的流体动力学方程。</span></span>\\n<span class=\\"line\\"><span></span></span>\\n<span class=\\"line\\"><span>使用机器学习方法：</span></span>\\n<span class=\\"line\\"><span>如果使用机器学习方法，我们会向机器学习模型提供大量天气数据，直到该模型最终学习到</span></span>\\n<span class=\\"line\\"><span>产生不同降雨量的天气模式之间的数学关系的【算法】。</span></span>\\n<span class=\\"line\\"><span>最终，我们只需向模型提供当前天气数据，让它预测降雨量。</span></span></code></pre>\\n<div class=\\"line-numbers\\" aria-hidden=\\"true\\" style=\\"counter-reset:line-number 0\\"><div class=\\"line-number\\"></div><div class=\\"line-number\\"></div><div class=\\"line-number\\"></div><div class=\\"line-number\\"></div><div class=\\"line-number\\"></div><div class=\\"line-number\\"></div><div class=\\"line-number\\"></div><div class=\\"line-number\\"></div><div class=\\"line-number\\"></div></div></div>","autoDesc":true}`),a={name:`AI与机器学习基础.md`};function o(r,i,a,o,s,c){return t(),e(`div`,null,[...i[0]||=[n(`<h1 id="ai与机器学习基础" tabindex="-1"><a class="header-anchor" href="#ai与机器学习基础"><span>AI与机器学习基础</span></a></h1><blockquote><p><code>Machine Learning</code> 是指硬件机器训练一段 <code>模型</code> 的软件，使其能够根据 <code>数据</code> 和 <code>算法</code> 做出有用的预测或生成内容（包含文本、图片、音频或视频），让机器从 <code>数据中学习</code> 规律而非显式编程。</p></blockquote><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>假设我们想要创建一个用于 预测降雨量 的应用。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>使用传统方法：</span></span>
<span class="line"><span>如果采用传统方法，我们需要创建地球大气层和地表的基于物理学的表示形式，并计算大量的流体动力学方程。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>使用机器学习方法：</span></span>
<span class="line"><span>如果使用机器学习方法，我们会向机器学习模型提供大量天气数据，直到该模型最终学习到</span></span>
<span class="line"><span>产生不同降雨量的天气模式之间的数学关系的【算法】。</span></span>
<span class="line"><span>最终，我们只需向模型提供当前天气数据，让它预测降雨量。</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h1 id="_1-机器学习的三大类" tabindex="-1"><a class="header-anchor" href="#_1-机器学习的三大类"><span>1. 机器学习的三大类</span></a></h1><h2 id="_1-1-监督学习-supervised-learning" tabindex="-1"><a class="header-anchor" href="#_1-1-监督学习-supervised-learning"><span>1.1 监督学习（Supervised Learning）</span></a></h2><p>核心思想：用 <code>带标签的数据</code> 训练模型，让模型学会从输入映射到输出。就像教小孩认动物：识别标注了&quot;猫&quot;、&quot;狗&quot;的图片，他就学会区分了。</p><p><strong>常见任务类型：</strong></p><ul><li><strong>分类（Classification）</strong>：预测离散类别。如垃圾邮件检测（是/否）、图像分类（猫/狗/鸟）</li><li><strong>回归（Regression）</strong>：预测连续数值。如房价预测、股价预测、温度预测</li></ul><p><strong>常见算法：</strong></p><table><thead><tr><th>算法</th><th>适用场景</th><th>优缺点</th></tr></thead><tbody><tr><td>逻辑回归</td><td>二分类问题</td><td>简单高效，可解释性好；非线性能力弱</td></tr><tr><td>决策树</td><td>分类/回归</td><td>直观可解释；容易过拟合</td></tr><tr><td>随机森林</td><td>通用分类/回归</td><td>鲁棒性好，不易过拟合；训练较慢</td></tr><tr><td>SVM</td><td>高维数据分类</td><td>泛化能力强；大数据集效率低</td></tr><tr><td>XGBoost</td><td>结构化数据竞赛常胜</td><td>精度高，速度快；参数调优复杂</td></tr></tbody></table><blockquote><p><strong>测试要点</strong>：监督学习模型的测试重点是评估预测准确性和泛化能力，核心指标包括 <code>准确率</code>、<code>精确率</code>、<code>召回率</code>、<code>F1值</code>、<code>AUC</code> 等。</p></blockquote><h2 id="_1-2-无监督学习-unsupervised-learning" tabindex="-1"><a class="header-anchor" href="#_1-2-无监督学习-unsupervised-learning"><span>1.2 无监督学习（Unsupervised Learning）</span></a></h2><p>核心思想：数据 <code>没有标签</code>，让模型自己发现数据中的结构和模式。就像给你一堆没有标签的照片，让你自己分成几组。</p><ul><li><strong>聚类（Clustering）</strong>：将数据分成若干组，例如 SQL <code>GROUP BY</code>、NumPy 的分组，如用户分群、异常检测</li><li><strong>降维（Dimensionality Reduction）</strong>：减少特征数量，如 PCA、t-SNE 可视化</li><li><strong>关联规则</strong>：发现数据间的关联，如购物篮分析</li></ul><h2 id="_1-3-强化学习-reinforcement-learning" tabindex="-1"><a class="header-anchor" href="#_1-3-强化学习-reinforcement-learning"><span>1.3 强化学习（Reinforcement Learning）</span></a></h2><p>核心思想：Agent（智能体）通过与环境交互，根据奖励/惩罚信号学习最优策略。就像训练宠物：做对了给奖励，做错了给惩罚，逐渐学会正确行为。</p><p>典型应用：游戏 AI（AlphaGo）、机器人控制、自动驾驶决策、推荐系统排序。</p><hr><h1 id="_2-模型-model-概念" tabindex="-1"><a class="header-anchor" href="#_2-模型-model-概念"><span>2. 模型（Model）概念</span></a></h1><ul><li>算法、模型和数据是机器学习的三大核心要素。</li><li><strong>算法</strong>是机器学习的基础，它决定了模型的学习方式和工作原理。</li><li><strong>模型</strong>是机器学习的成果，它可以用于预测、分类、分析等任务。</li><li><strong>数据</strong>是机器学习的燃料，它为模型提供学习和训练所需的信息。</li></ul><p>在机器学习中，不同类型的模型（聚类模型、递归模型、拟合模型、分类模型）有各自的评估方法和标准。以下是对这些模型的评估方法、标准定义以及应用场景的详细说明。</p><h2 id="_2-1-聚类模型-clustering-model" tabindex="-1"><a class="header-anchor" href="#_2-1-聚类模型-clustering-model"><span>2.1 聚类模型（Clustering Model）</span></a></h2><p>聚类模型用于将数据集划分为多个组（簇），目的是使同一簇中的数据点尽可能相似，不同簇的数据点尽可能不同。</p><p>常见的聚类算法包括 <code>K-means</code>、<code>层次聚类</code>、<code>DBSCAN</code> 等。</p><p><strong>评估指标：</strong></p><ol><li><p><strong>轮廓系数（Silhouette Coefficient）</strong>：衡量样本在其聚类中的紧密度和与其他聚类的分离度。</p><ul><li><p>计算公式：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mtext>Silhouette\xA0Score</mtext><mo>=</mo><mfrac><mrow><mi>b</mi><mo>−</mo><mi>a</mi></mrow><mrow><mi>max</mi><mo>⁡</mo><mo stretchy="false">(</mo><mi>a</mi><mo separator="true">,</mo><mi>b</mi><mo stretchy="false">)</mo></mrow></mfrac></mrow><annotation encoding="application/x-tex">\\text{Silhouette Score} = \\frac{b - a}{\\max(a, b)} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord text"><span class="mord">Silhouette\xA0Score</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.3074em;vertical-align:-0.936em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3714em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mop">max</span><span class="mopen">(</span><span class="mord mathnormal">a</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">b</span><span class="mclose">)</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord mathnormal">b</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord mathnormal">a</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.936em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span></span></span></span></span></p><ul><li><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>a</mi></mrow><annotation encoding="application/x-tex">a</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">a</span></span></span></span>：样本到同簇其他点的平均距离</li><li><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>b</mi></mrow><annotation encoding="application/x-tex">b</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal">b</span></span></span></span>：样本到最近簇中点的平均距离</li></ul></li><li><p>取值范围：<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo stretchy="false">[</mo><mo>−</mo><mn>1</mn><mo separator="true">,</mo><mn>1</mn><mo stretchy="false">]</mo></mrow><annotation encoding="application/x-tex">[-1, 1]</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">[</span><span class="mord">−</span><span class="mord">1</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">1</span><span class="mclose">]</span></span></span></span>，接近 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>1</mn></mrow><annotation encoding="application/x-tex">1</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">1</span></span></span></span> 表示聚类效果好。</p></li></ul></li><li><p><strong>互信息（Mutual Information, MI）</strong>：衡量聚类结果与真实标签之间的信息共享量。</p><ul><li>无单位量纲，值越高表示越好的聚类效果。</li></ul></li><li><p><strong>轮廓分数（Silhouette Score）</strong>：计算每个点的轮廓系数，取平均值。</p></li><li><p><strong>Calinski-Harabasz Index</strong>：衡量聚类的紧密度和分离度。</p></li><li><p><strong>调整兰德指数（Adjusted Rand Index, ARI）</strong>：</p><ul><li>衡量聚类结果与真实标签的相似度，考虑了随机聚类的影响。</li><li>取值范围：<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo stretchy="false">[</mo><mo>−</mo><mn>1</mn><mo separator="true">,</mo><mn>1</mn><mo stretchy="false">]</mo></mrow><annotation encoding="application/x-tex">[-1, 1]</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">[</span><span class="mord">−</span><span class="mord">1</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">1</span><span class="mclose">]</span></span></span></span>，值越高越好。</li></ul></li><li><p><strong>聚类内平均距离（Inertia）</strong>：</p><ul><li>计算各点到其聚类中心的平方距离和，常用于 K-means 算法。</li><li>值越小，表示聚类效果越好。</li></ul></li></ol><p><strong>标准定义：</strong></p><ul><li>轮廓系数：值在 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo stretchy="false">[</mo><mo>−</mo><mn>1</mn><mo separator="true">,</mo><mn>1</mn><mo stretchy="false">]</mo></mrow><annotation encoding="application/x-tex">[-1, 1]</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">[</span><span class="mord">−</span><span class="mord">1</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">1</span><span class="mclose">]</span></span></span></span> 之间，越接近 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>1</mn></mrow><annotation encoding="application/x-tex">1</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">1</span></span></span></span> 表示聚类效果越好。</li><li>互信息：值在 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo stretchy="false">[</mo><mn>0</mn><mo separator="true">,</mo><mn>1</mn><mo stretchy="false">]</mo></mrow><annotation encoding="application/x-tex">[0, 1]</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">[</span><span class="mord">0</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">1</span><span class="mclose">]</span></span></span></span> 之间，越接近 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>1</mn></mrow><annotation encoding="application/x-tex">1</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">1</span></span></span></span> 表示聚类结果与真实标签越一致。</li><li>Calinski-Harabasz Index：值越大表示聚类效果越好。</li></ul><p><strong>应用场景：</strong></p><ul><li>客户细分：根据购买行为将客户分成不同群体。</li><li>图像分割：将图像中的像素分成不同区域。</li><li>市场分析：根据消费者行为数据进行市场细分。</li></ul><h2 id="_2-2-递归模型-recursive-model" tabindex="-1"><a class="header-anchor" href="#_2-2-递归模型-recursive-model"><span>2.2 递归模型（Recursive Model）</span></a></h2><p>递归模型，如递归神经网络（RNN）和长短期记忆网络（LSTM），通常用于处理时间序列数据、自然语言处理等任务。这些模型能够捕捉数据中的时间依赖性和序列关系。</p><p><strong>评估方法：</strong></p><table><thead><tr><th>指标</th><th>说明</th></tr></thead><tbody><tr><td>均方误差（MSE）</td><td>衡量预测值与真实值之间的平均平方误差</td></tr><tr><td>平均绝对误差（MAE）</td><td>衡量预测值与真实值之间的平均绝对误差</td></tr><tr><td><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mi>R</mi><mn>2</mn></msup></mrow><annotation encoding="application/x-tex">R^2</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0077em;">R</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span></span></span></span>（决定系数）</td><td>衡量模型解释数据变异的能力</td></tr></tbody></table><p>此外，特定任务还可以使用以下指标：</p><ul><li><strong>困惑度（Perplexity）</strong>：模型对给定序列的平均预测概率的倒数。</li><li><strong>BLEU 分数（BLEU Score）</strong>：用于评价机器翻译质量的指标。</li><li><strong>ROUGE 分数（ROUGE Score）</strong>：用于评价文本摘要质量的指标。</li></ul><blockquote><p>选择合适的评价指标取决于具体的任务和模型的类型。</p></blockquote><p><strong>标准定义：</strong></p><ul><li>均方误差（MSE）：值越小表示模型预测效果越好。</li><li>平均绝对误差（MAE）：值越小表示模型预测效果越好。</li><li><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mi>R</mi><mn>2</mn></msup></mrow><annotation encoding="application/x-tex">R^2</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0077em;">R</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span></span></span></span>：值在 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo stretchy="false">[</mo><mn>0</mn><mo separator="true">,</mo><mn>1</mn><mo stretchy="false">]</mo></mrow><annotation encoding="application/x-tex">[0, 1]</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">[</span><span class="mord">0</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">1</span><span class="mclose">]</span></span></span></span> 之间，越接近 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>1</mn></mrow><annotation encoding="application/x-tex">1</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">1</span></span></span></span> 表示模型解释能力越强。</li></ul><p><strong>应用场景：</strong></p><ul><li>时间序列预测：如股票价格预测、天气预报。</li><li>自然语言处理：如文本生成、机器翻译。</li><li>信号处理：如语音识别、图像处理。</li></ul><h2 id="_2-3-拟合模型-fitting-model" tabindex="-1"><a class="header-anchor" href="#_2-3-拟合模型-fitting-model"><span>2.3 拟合模型（Fitting Model）</span></a></h2><p>拟合模型（回归模型）用于预测连续型输出变量。常见的回归模型包括线性回归、岭回归、Lasso 回归等。</p><p><strong>评估方法：</strong></p><ol><li><strong>均方误差（MSE）</strong>：衡量模型预测值与真实值之间的平均平方误差。</li><li><strong><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mi>R</mi><mn>2</mn></msup></mrow><annotation encoding="application/x-tex">R^2</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0077em;">R</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span></span></span></span>（决定系数）</strong>：衡量模型解释数据变异的能力。</li><li><strong>交叉验证（Cross-Validation）</strong>：通过多次训练和验证来评估模型的稳定性和泛化能力。</li></ol><p><strong>标准定义：</strong></p><ul><li>均方误差（MSE）：值越小表示模型拟合效果越好。</li><li><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mi>R</mi><mn>2</mn></msup></mrow><annotation encoding="application/x-tex">R^2</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0077em;">R</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span></span></span></span>：值在 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo stretchy="false">[</mo><mn>0</mn><mo separator="true">,</mo><mn>1</mn><mo stretchy="false">]</mo></mrow><annotation encoding="application/x-tex">[0, 1]</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">[</span><span class="mord">0</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">1</span><span class="mclose">]</span></span></span></span> 之间，越接近 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>1</mn></mrow><annotation encoding="application/x-tex">1</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">1</span></span></span></span> 表示模型拟合效果越好。</li></ul><p><strong>应用场景：</strong></p><ul><li>回归分析：如房价预测、销售额预测。</li><li>曲线拟合：如物理实验数据拟合、经济数据分析。</li><li>生物统计：如药物剂量反应曲线拟合。</li></ul><h2 id="_2-4-分类模型-classification-model" tabindex="-1"><a class="header-anchor" href="#_2-4-分类模型-classification-model"><span>2.4 分类模型（Classification Model）</span></a></h2><p>分类模型用于将数据点分为不同的类别。常见的分类算法包括逻辑回归、支持向量机（SVM）、决策树、随机森林、K 近邻（KNN）和神经网络等。</p><p><strong>评估方法：</strong></p><table><thead><tr><th>指标</th><th>说明</th></tr></thead><tbody><tr><td>准确率（Accuracy）</td><td>正确分类的样本数占总样本数的比例</td></tr><tr><td>查准率（Precision）</td><td>预测为正类的样本中实际为正类的比例</td></tr><tr><td>召回率（Recall）</td><td>实际为正类的样本中被正确预测为正类的比例</td></tr><tr><td>F1 值（F1 Score）</td><td>查准率和召回率的调和平均数</td></tr><tr><td>ROC 曲线</td><td>通过绘制真阳性率和假阳性率来评估模型性能</td></tr></tbody></table><p><strong>标准定义：</strong></p><ul><li><p><strong>准确率（Accuracy）</strong>：值越高表示模型分类效果越好。</p><ul><li><p>计算公式：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mtext>Accuracy</mtext><mo>=</mo><mfrac><mtext>正确预测数</mtext><mtext>总预测数</mtext></mfrac></mrow><annotation encoding="application/x-tex">\\text{Accuracy} = \\frac{\\text{正确预测数}}{\\text{总预测数}} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8778em;vertical-align:-0.1944em;"></span><span class="mord text"><span class="mord">Accuracy</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.0463em;vertical-align:-0.686em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3603em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord text"><span class="mord cjk_fallback">总预测数</span></span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord text"><span class="mord cjk_fallback">正确预测数</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.686em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span></span></span></span></span></p></li><li><p>优点：简单直观。</p></li><li><p>缺点：在类别不均衡的数据集上，可能会产生误导性的高准确率。</p></li></ul></li><li><p><strong>精确率（Precision）</strong>：衡量预测为正类的样本中实际为正类的比例。</p><ul><li><p>计算公式：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mtext>Precision</mtext><mo>=</mo><mfrac><mrow><mi>T</mi><mi>P</mi></mrow><mrow><mi>T</mi><mi>P</mi><mo>+</mo><mi>F</mi><mi>P</mi></mrow></mfrac></mrow><annotation encoding="application/x-tex">\\text{Precision} = \\frac{TP}{TP + FP} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord text"><span class="mord">Precision</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.1297em;vertical-align:-0.7693em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3603em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">F</span><span class="mord mathnormal" style="margin-right:0.1389em;">P</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="mord mathnormal" style="margin-right:0.1389em;">P</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.7693em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span></span></span></span></span></p></li><li><p>高精确率表示假阳性（False Positive）较少。</p></li></ul></li><li><p><strong>召回率（Recall）</strong>：衡量实际为正类的样本中被正确预测为正类的比例。</p><ul><li><p>计算公式：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mtext>Recall</mtext><mo>=</mo><mfrac><mrow><mi>T</mi><mi>P</mi></mrow><mrow><mi>T</mi><mi>P</mi><mo>+</mo><mi>F</mi><mi>N</mi></mrow></mfrac></mrow><annotation encoding="application/x-tex">\\text{Recall} = \\frac{TP}{TP + FN} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord text"><span class="mord">Recall</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.1297em;vertical-align:-0.7693em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3603em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">F</span><span class="mord mathnormal" style="margin-right:0.109em;">N</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="mord mathnormal" style="margin-right:0.1389em;">P</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.7693em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span></span></span></span></span></p></li><li><p>高召回率表示假阴性（False Negative）较少。</p></li></ul></li><li><p><strong>F1 分数（F1 Score）</strong>：精确率和召回率的调和平均数。</p><ul><li><p>计算公式：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><msub><mi>F</mi><mn>1</mn></msub><mo>=</mo><mn>2</mn><mo>×</mo><mfrac><mrow><mtext>Precision</mtext><mo>×</mo><mtext>Recall</mtext></mrow><mrow><mtext>Precision</mtext><mo>+</mo><mtext>Recall</mtext></mrow></mfrac></mrow><annotation encoding="application/x-tex">F_1 = 2 \\times \\frac{\\text{Precision} \\times \\text{Recall}}{\\text{Precision} + \\text{Recall}} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">F</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">2</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:2.1408em;vertical-align:-0.7693em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3714em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord text"><span class="mord">Precision</span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord text"><span class="mord">Recall</span></span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord text"><span class="mord">Precision</span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord text"><span class="mord">Recall</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.7693em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span></span></span></span></span></p></li><li><p>在精确率和召回率之间取得平衡，适用于类别不均衡的数据集。</p></li></ul></li><li><p><strong>ROC 曲线及 AUC</strong>：</p><ul><li><p>ROC 曲线：绘制真正率（TPR）对假正率（FPR）的曲线。</p></li><li><p>AUC：ROC 曲线下的面积，值越大表示模型效果越好（最大值为 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>1</mn></mrow><annotation encoding="application/x-tex">1</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">1</span></span></span></span>）。</p></li><li><p>计算公式：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mi>T</mi><mi>P</mi><mi>R</mi><mo>=</mo><mfrac><mrow><mi>T</mi><mi>P</mi></mrow><mrow><mi>T</mi><mi>P</mi><mo>+</mo><mi>F</mi><mi>N</mi></mrow></mfrac></mrow><annotation encoding="application/x-tex">TPR = \\frac{TP}{TP + FN} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="mord mathnormal" style="margin-right:0.0077em;">R</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.1297em;vertical-align:-0.7693em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3603em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">F</span><span class="mord mathnormal" style="margin-right:0.109em;">N</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="mord mathnormal" style="margin-right:0.1389em;">P</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.7693em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span></span></span></span></span></p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mi>F</mi><mi>P</mi><mi>R</mi><mo>=</mo><mfrac><mrow><mi>F</mi><mi>P</mi></mrow><mrow><mi>F</mi><mi>P</mi><mo>+</mo><mi>T</mi><mi>N</mi></mrow></mfrac></mrow><annotation encoding="application/x-tex">FPR = \\frac{FP}{FP + TN} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">F</span><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="mord mathnormal" style="margin-right:0.0077em;">R</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.1297em;vertical-align:-0.7693em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3603em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">F</span><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="mord mathnormal" style="margin-right:0.109em;">N</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">F</span><span class="mord mathnormal" style="margin-right:0.1389em;">P</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.7693em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span></span></span></span></span></p></li></ul></li><li><p><strong>混淆矩阵（Confusion Matrix）</strong>：</p><ul><li>二分类问题中，混淆矩阵显示了预测结果与实际结果的对照情况。</li><li>包含四个要素：真正类（TP）、假正类（FP）、假负类（FN）、真负类（TN）。</li><li>通过混淆矩阵可以计算多种评价指标，如准确率、精确率、召回率和 F1 分数。</li></ul></li></ul><p><strong>应用场景：</strong></p><ul><li>垃圾邮件检测：将邮件分类为垃圾邮件或正常邮件。</li><li>疾病诊断：根据症状和检查结果分类是否患有某种疾病。</li><li>图像分类：将图像分类为不同类别，如猫、狗、鸟等。</li></ul><h2 id="模型总结" tabindex="-1"><a class="header-anchor" href="#模型总结"><span>模型总结</span></a></h2><table><thead><tr><th>模型类型</th><th>主要用途</th><th>核心评估指标</th></tr></thead><tbody><tr><td>聚类模型</td><td>数据分群</td><td>轮廓系数、CH 指数、ARI</td></tr><tr><td>递归模型</td><td>时间序列预测 / 序列数据处理</td><td>MSE、MAE、<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mi>R</mi><mn>2</mn></msup></mrow><annotation encoding="application/x-tex">R^2</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0077em;">R</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span></span></span></span></td></tr><tr><td>拟合模型</td><td>数据拟合 / 回归分析</td><td><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mi>R</mi><mn>2</mn></msup></mrow><annotation encoding="application/x-tex">R^2</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0077em;">R</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span></span></span></span>、MSE</td></tr><tr><td>分类模型</td><td>分类任务</td><td>准确率、精确率、召回率、F1、AUC</td></tr></tbody></table><hr><h1 id="_3-如何判断模型的类型" tabindex="-1"><a class="header-anchor" href="#_3-如何判断模型的类型"><span>3. 如何判断模型的类型</span></a></h1><p>面对一个陌生的模型时，可以从以下四个维度快速判断它属于哪种模型类型：</p><h2 id="_3-1-看输出" tabindex="-1"><a class="header-anchor" href="#_3-1-看输出"><span>3.1 看输出</span></a></h2><table><thead><tr><th>输出类型</th><th>对应模型类型</th><th>例子</th></tr></thead><tbody><tr><td>离散类别/标签</td><td>分类模型</td><td>垃圾邮件 vs 正常邮件、猫/狗/鸟</td></tr><tr><td>连续数值</td><td>拟合模型（回归）</td><td>房价 350 万、温度 26.5°C</td></tr><tr><td>分组/簇</td><td>聚类模型</td><td>用户分群 A/B/C、图像区域分割</td></tr><tr><td>序列（文本/时间序列）</td><td>递归模型</td><td>机器翻译、股价走势预测</td></tr></tbody></table><blockquote><p><strong>核心判断</strong>：模型输出的「形状」决定了模型类型。输出是类别就是分类，输出是数值就是回归，输出是分组就是聚类。</p></blockquote><h2 id="_3-2-看训练数据" tabindex="-1"><a class="header-anchor" href="#_3-2-看训练数据"><span>3.2 看训练数据</span></a></h2><table><thead><tr><th>数据特征</th><th>对应模型类型</th><th>关键信号</th></tr></thead><tbody><tr><td>有标签 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>y</mi></mrow><annotation encoding="application/x-tex">y</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">y</span></span></span></span></td><td>监督学习（分类/回归/递归）</td><td>输入 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>X</mi></mrow><annotation encoding="application/x-tex">X</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0785em;">X</span></span></span></span> 和输出 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>y</mi></mrow><annotation encoding="application/x-tex">y</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">y</span></span></span></span> 成对出现</td></tr><tr><td>无标签</td><td>无监督学习（聚类/降维）</td><td>只有输入 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>X</mi></mrow><annotation encoding="application/x-tex">X</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0785em;">X</span></span></span></span>，没有 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>y</mi></mrow><annotation encoding="application/x-tex">y</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">y</span></span></span></span></td></tr><tr><td>有奖励信号</td><td>强化学习</td><td>不是直接标签，而是环境反馈的 reward</td></tr></tbody></table><h2 id="_3-3-看核心算法" tabindex="-1"><a class="header-anchor" href="#_3-3-看核心算法"><span>3.3 看核心算法</span></a></h2><table><thead><tr><th>算法名</th><th>模型类型</th><th>一句话识别</th></tr></thead><tbody><tr><td>逻辑回归、SVM、决策树、随机森林、XGBoost</td><td>分类模型</td><td>名字带「分类」或输出离散值</td></tr><tr><td>线性回归、岭回归、Lasso</td><td>拟合模型</td><td>名字带「回归」或输出连续值</td></tr><tr><td>K-means、DBSCAN、层次聚类</td><td>聚类模型</td><td>名字带「聚类」或无监督分组</td></tr><tr><td>RNN、LSTM、GRU、Transformer</td><td>递归模型</td><td>处理序列数据，有「记忆」结构</td></tr></tbody></table><h2 id="_3-4-看评估指标" tabindex="-1"><a class="header-anchor" href="#_3-4-看评估指标"><span>3.4 看评估指标</span></a></h2><p>如果你能看到模型的评估报告，指标也能直接暴露类型：</p><ul><li>看到 <strong>Accuracy、Precision、Recall、F1、AUC</strong> → 分类模型</li><li>看到 <strong>MSE、MAE、<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mi>R</mi><mn>2</mn></msup></mrow><annotation encoding="application/x-tex">R^2</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0077em;">R</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span></span></span></span></strong> → 拟合模型（回归）或递归模型</li><li>看到 <strong>轮廓系数、CH Index、ARI</strong> → 聚类模型</li><li>看到 <strong>BLEU、ROUGE、困惑度（Perplexity）</strong> → 递归模型（NLP 方向）</li></ul><h2 id="_3-5-快速判断流程图" tabindex="-1"><a class="header-anchor" href="#_3-5-快速判断流程图"><span>3.5 快速判断流程图</span></a></h2><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>模型的输出是？</span></span>
<span class="line"><span>  ├─ 类别/标签 ──→ 分类模型</span></span>
<span class="line"><span>  ├─ 连续数值 ──→ 是序列数据吗？</span></span>
<span class="line"><span>  │                 ├─ 是 ──→ 递归模型</span></span>
<span class="line"><span>  │                 └─ 否 ──→ 拟合模型（回归）</span></span>
<span class="line"><span>  └─ 分组/簇   ──→ 聚类模型</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p><strong>总结</strong>：先看输出类型，再看训练数据是否有标签，最后用算法名和评估指标交叉验证 —— 三个维度一致，就能确定模型类型。</p></blockquote><hr><h1 id="_4-算法" tabindex="-1"><a class="header-anchor" href="#_4-算法"><span>4.算法</span></a></h1><p>算法简介</p><ul><li><strong>KMeans 算法:</strong> KMeans 算法是一种基于原型的聚类算法，其目标是将数据点划分成 K 个簇，使得每个簇内的点尽可能相似，而不同簇之间的点尽可能不同。</li><li><strong>层次聚类算法:</strong> 层次聚类算法是一种自底向上的聚类算法，其工作原理是先将数据点两两聚类，然后逐步合并相似度较高的簇，直到形成所需的簇数。</li><li><strong>DBSCAN 算法:</strong> DBSCAN 算法是一种密度聚类算法，其工作原理是将密度较高的区域划分为簇，而密度较低的区域则视为噪声点。</li><li><strong>循环神经网络 (RNN):</strong> 循环神经网络是一种能够处理序列数据的模型，其核心思想是让神经元的输出不仅依赖于当前的输入，还依赖于上一次的输出。</li><li><strong>长短期记忆网络 (LSTM):</strong> 长短期记忆网络是一种改进的循环神经网络，其主要特点是引入了一种称为门控机制的结构，能够更好地捕捉长距离依赖关系。</li><li><strong>门控循环单元 (GRU):</strong> 门控循环单元是另一种改进的循环神经网络，其主要特点是简化了门控机制，在保持性能的同时降低了计算复杂度。</li><li><strong>线性回归:</strong> 线性回归是一种用于预测连续型目标变量的模型，其假设是目标变量与自变量之间存在线性关系。</li><li><strong>逻辑回归:</strong> 逻辑回归是一种用于预测离散型目标变量的模型，其假设是目标变量服从伯努利分布。</li><li><strong>决策树:</strong> 决策树是一种树状结构的分类模型，其工作原理是根据特征值对数据进行递归划分，直到形成最终的分类结果。</li><li><strong>支持向量机 (SVM):</strong> 支持向量机是一种用于分类和回归的模型，其核心思想是找到能够最大化间隔的超平面，将数据点划分为不同的类别。</li><li><strong>朴素贝叶斯:</strong> 朴素贝叶斯是一种基于贝叶斯定理的分类模型，其假设是特征之间相互独立。</li><li><strong>随机森林:</strong> 随机森林是一种集成学习模型，其工作原理是训练多个决策树，然后根据投票结果进行预测。</li><li><strong>梯度提升决策树 (GBDT):</strong> 梯度提升决策树是一种集成学习模型，其工作原理是逐棵训练决策树，并根据每个决策树的残差进行修正。</li></ul><h2 id="_4-1-不同类型模型的算法总结" tabindex="-1"><a class="header-anchor" href="#_4-1-不同类型模型的算法总结"><span>4.1 不同类型模型的算法总结</span></a></h2><table><thead><tr><th>模型类型</th><th>算法</th><th>优缺点</th><th>应用场景</th></tr></thead><tbody><tr><td>聚类模型</td><td>- KMeans 算法（K 均值）<br>- 层次聚类算法<br>- DBSCAN 算法</td><td>- 简单易用，易于解释<br>- 对异常点敏感<br>- 难以处理高维数据</td><td>- 客户细分<br>- 市场营销<br>- 文档聚类</td></tr><tr><td>递归模型</td><td>- 循环神经网络 (RNN)<br>- 长短期记忆网络 (LSTM)<br>- 门控循环单元 (GRU)</td><td>- 擅长处理序列数据<br>- 能够捕捉长距离依赖关系<br>- 参数较多，训练难度较大</td><td>- 机器翻译<br>- 语音识别<br>- 自然语言处理</td></tr><tr><td>拟合模型</td><td>- 线性回归<br>- 逻辑回归<br>- 决策树<br>- 支持向量机 (SVM)</td><td>- 简单易用，易于解释<br>- 能够对数据进行非线性拟合<br>- 存在过拟合风险</td><td>- 预测房价<br>- 医学诊断<br>- 欺诈检测</td></tr><tr><td>分类模型</td><td>- 朴素贝叶斯<br>- 随机森林<br>- 梯度提升决策树 (GBDT)</td><td>- 鲁棒性强，不易受异常点影响<br>- 能够处理高维数据<br>- 难以解释模型结果</td><td>- 垃圾邮件过滤<br>- 信用评分<br>- 医学诊断</td></tr></tbody></table><h2 id="_4-2-逻辑回归与-线性回归" tabindex="-1"><a class="header-anchor" href="#_4-2-逻辑回归与-线性回归"><span>4.2 逻辑回归与 线性回归</span></a></h2><blockquote><p>逻辑回归和线性回归都是机器学习中常用的算法，但它们在目标、方法和应用场景上存在<strong>本质区别</strong>。</p></blockquote><h3 id="目标" tabindex="-1"><a class="header-anchor" href="#目标"><span>目标</span></a></h3><ul><li><strong>线性回归</strong>：旨在预测<strong>连续</strong>的<strong>目标变量</strong>。例如，预测房价、体重或考试成绩等。</li><li><strong>逻辑回归</strong>：旨在预测<strong>二分类</strong>的<strong>目标变量</strong>。例如，预测电子邮件是否为垃圾邮件、用户是否会购买产品或患者是否患有某种疾病等。</li></ul><h3 id="方法" tabindex="-1"><a class="header-anchor" href="#方法"><span>方法</span></a></h3><ul><li><strong>线性回归</strong>：使用<strong>线性函数</strong>来拟合数据。该线性函数将输入变量映射到一个实数值，即预测值。</li><li><strong>逻辑回归</strong>：使用<strong>逻辑函数</strong>（例如sigmoid函数）将线性函数的输出映射到一个介于0和1之间的概率值，表示数据属于某一类的可能性。</li></ul><h3 id="模型参数" tabindex="-1"><a class="header-anchor" href="#模型参数"><span>模型参数</span></a></h3><ul><li><strong>线性回归</strong>：模型参数包括<strong>偏置项</strong>和<strong>回归系数</strong>。偏置项是模型预测值的基础值，回归系数衡量输入变量对预测值的影响程度。</li><li><strong>逻辑回归</strong>：模型参数也包括偏置项和回归系数，但它们的含义与线性回归中不同。在逻辑回归中，回归系数衡量输入变量对<strong>对数几率</strong>的影响程度。</li></ul><h3 id="训练" tabindex="-1"><a class="header-anchor" href="#训练"><span>训练</span></a></h3><ul><li><strong>线性回归</strong>：通常使用<strong>最小二乘法</strong>来训练模型，即最小化预测值与真实值之间的平方差。</li><li><strong>逻辑回归</strong>：通常使用<strong>最大似然估计</strong>或<strong>最小交叉熵</strong>来训练模型。</li></ul><h3 id="评估" tabindex="-1"><a class="header-anchor" href="#评估"><span>评估</span></a></h3><ul><li><strong>线性回归</strong>：常用的评估指标包括<strong>均方误差（MSE）</strong>、<strong>平均绝对误差（MAE）</strong>和<strong>R平方值</strong>等。</li><li><strong>逻辑回归</strong>：常用的评估指标包括<strong>准确率</strong>、<strong>召回率</strong>、<strong>F1分数</strong>和<strong>ROC曲线</strong>等。</li></ul><h3 id="应用场景" tabindex="-1"><a class="header-anchor" href="#应用场景"><span>应用场景</span></a></h3><ul><li><strong>线性回归</strong>：广泛应用于<strong>预测</strong>和<strong>回归</strong>任务，例如房价预测、股票价格预测和需求预测等。</li><li><strong>逻辑回归</strong>：广泛应用于<strong>分类</strong>任务，例如垃圾邮件识别、信用卡欺诈检测和医学诊断等。</li></ul><h3 id="总结" tabindex="-1"><a class="header-anchor" href="#总结"><span>总结</span></a></h3><table><thead><tr><th>特征</th><th>线性回归</th><th>逻辑回归</th></tr></thead><tbody><tr><td>目标</td><td>预测连续的目标变量</td><td>预测二分类的目标变量</td></tr><tr><td>方法</td><td>使用线性函数</td><td>使用逻辑函数</td></tr><tr><td>模型参数</td><td>偏置项和回归系数</td><td>偏置项和回归系数</td></tr><tr><td>训练</td><td>最小二乘法</td><td>最大似然估计或最小交叉熵</td></tr><tr><td>评估</td><td>MSE、MAE、R平方值等</td><td>准确率、召回率、F1分数、ROC曲线等</td></tr><tr><td>应用场景</td><td>预测、回归</td><td>分类</td></tr></tbody></table><p>以下是一些具体的例子：</p><ul><li><strong>预测房价</strong>：可以使用线性回归模型来预测房价。输入变量可以包括房屋面积、房间数、地理位置等，目标变量是房价。</li><li><strong>识别垃圾邮件</strong>：可以使用逻辑回归模型来识别垃圾邮件。输入变量可以包括电子邮件的主题、内容、发件人等，目标变量是电子邮件是否为垃圾邮件。</li><li><strong>诊断医学疾病</strong>：可以使用逻辑回归模型来诊断医学疾病。输入变量可以包括患者的症状、体征、检查结果等，目标变量是患者是否患有某种疾病。</li></ul><h1 id="_4-深度学习核心概念" tabindex="-1"><a class="header-anchor" href="#_4-深度学习核心概念"><span>4. 深度学习核心概念</span></a></h1><h2 id="_4-1-神经网络基础" tabindex="-1"><a class="header-anchor" href="#_4-1-神经网络基础"><span>4.1 神经网络基础</span></a></h2><p>神经网络由输入层、隐藏层、输出层组成。每个神经元接收输入，通过<code>权重加和</code>后经过激活函数产生输出。<br> 训练过程就是通过<code>反向传播算法不断调整权重</code>，使模型的预测结果与真实标签之间的损失函数最小化。</p><p><strong>关键术语：</strong></p><ul><li><strong>权重（Weight）和偏置（Bias）</strong>：模型的可学习参数</li><li><strong>激活函数（Activation）</strong>：引入非线性，如 ReLU、Sigmoid、Softmax</li><li><strong>损失函数（Loss）</strong>：衡量预测与真实之间的差距，如交叉熵、MSE</li><li><strong>优化器（Optimizer）</strong>：更新参数的算法，如 SGD、Adam</li><li><strong>学习率（Learning Rate）</strong>：参数更新的步长，太大震荡，太小收敛慢</li><li><strong>过拟合（Overfitting）</strong>：模型记住训练数据但泛化能力差，应当<code>减少特征</code>,<code>SMOTE处理不平衡</code>,<code>调低学习率</code></li><li><strong>欠拟合</strong>: 模型太简单没有学习完整,应当<code>增加特征</code>,<code>换复杂模型</code></li><li><strong>正则化（Regularization）</strong>：防止过拟合的技术，如 Dropout、L2 正则</li></ul><h2 id="_5-2-主要网络架构" tabindex="-1"><a class="header-anchor" href="#_5-2-主要网络架构"><span>5.2 主要网络架构</span></a></h2><table><thead><tr><th>架构</th><th>核心思想</th><th>典型应用</th></tr></thead><tbody><tr><td>CNN卷积神经网络</td><td>通过卷积核提取空间特征</td><td>图像分类/目标检测/OCR</td></tr><tr><td>RNN循环神经网络</td><td>处理序列数据，有记忆能力</td><td>时间序列/早期NLP</td></tr><tr><td>LSTM/GRU</td><td>解决RNN长距离依赖问题</td><td>语音识别/机器翻译</td></tr><tr><td>Transformer</td><td>自注意力机制，并行处理</td><td>GPT/BERT/所有现代LLM</td></tr><tr><td>GAN生成对抗网络</td><td>生成器vs判别器对抗训练</td><td>图像生成/数据增强</td></tr><tr><td>扩散模型</td><td>从噪声逐步去噪生成内容</td><td>Stable Diffusion/DALL-E</td></tr></tbody></table><h2 id="_5-3-transformer与大语言模型" tabindex="-1"><a class="header-anchor" href="#_5-3-transformer与大语言模型"><span>5.3 Transformer与大语言模型</span></a></h2><p>Transformer 是 2017 年 Google 提出的架构，其核心创新是自注意力（Self-Attention）机制，能够捕捉序列中任意位置之间的依赖关系。这一架构彻底改变了 NLP 领域，并成为所有现代大语言模型的基础。</p><p>GPT 系列（Generative Pre-trained Transformer）采用 Decoder-only 架构，通过海量文本数据预训练，学会了预测下一个 token。模型规模从 GPT-2 的 15 亿参数到 GPT-4 的数万亿参数，涌现出了推理、编程、创作等能力。</p><blockquote><p><strong>测试视角</strong>：理解 Transformer 架构有助于理解 LLM 的能力边界——它本质上是在做条件概率预测，这解释了为什么会产生幻觉（自信地编造事实）。</p></blockquote><h1 id="_6-ai系统的完整生命周期" tabindex="-1"><a class="header-anchor" href="#_6-ai系统的完整生命周期"><span>6. AI系统的完整生命周期</span></a></h1><p>理解 AI 系统的生命周期对于确定测试切入点至关重要：</p><ol><li><strong>数据收集与准备</strong>：采集原始数据、数据清洗、数据标注、数据增强、特征工程</li><li><strong>模型训练</strong>：选择算法、配置超参数、模型训练、交叉验证</li><li><strong>模型评估</strong>：离线评估（准确率等指标）、A/B 测试、人工评估</li><li><strong>模型部署</strong>：模型序列化、服务化部署、API 封装、负载均衡</li><li><strong>模型监控</strong>：性能监控、数据漂移检测、模型漂移检测、告警</li><li><strong>模型迭代</strong>：根据线上反馈收集新数据、重新训练、灰度发布</li></ol><p><strong>每个阶段都需要测试！</strong> 数据阶段需要数据质量测试，训练阶段需要训练过程验证，评估阶段需要全面的指标评测，部署阶段需要集成测试和性能测试，监控阶段需要持续的漂移检测和告警验证。</p>`,114)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};